package wgmodern;
import net.minecraft.client.Minecraft;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.core.Direction;import net.minecraft.world.item.*;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;
public class CuttingRenderer implements BlockEntityRenderer<CuttingTable.Tile> {
 private static final ResourceLocation TEXTURE=new ResourceLocation("witchinggadgets","textures/models/cuttingtable.png");
 private static ModelPart model;
 public CuttingRenderer(BlockEntityRendererProvider.Context c){}
 private static void box(PartDefinition r,String name,int u,int v,float x,float y,float z,float sx,float sy,float sz,float ry){r.addOrReplaceChild(name,CubeListBuilder.create().texOffs(u,v).mirror().addBox(0,0,0,sx,sy,sz),PartPose.offsetAndRotation(x,y,z,0,ry,0));}
 public static ModelPart model(){if(model!=null)return model;var mesh=new MeshDefinition();var r=mesh.getRoot();box(r,"bottom",0,0,-8,0,-8,16,2,16,0);box(r,"top",0,0,-8,10,-8,16,4,16,0);box(r,"carpet",-32,0,-8,14.05f,-8,16,0,16,0);for(int i=0;i<4;i++)box(r,"leg"+i,0,20,i%2==0?-7:4,2,i<2?-7:4,3,8,3,0);box(r,"quartz1",52,0,4.8f,13.9f,2.2f,1,1,1,.4f);box(r,"quartz2",52,0,7,14,-2.5f,1,1,5,-.4f);box(r,"flint1",52,6,-6,13.9f,-.8f,1,1,2,-.1f);box(r,"flint2",52,0,-6.5f,14,-5.5f,1,1,5,.1f);box(r,"iron1",52,1,4.5f,14,-5.5f,1,1,4,0);box(r,"iron2",58,6,4.5f,13.9f,-2.8f,1,1,2,-.1f);
 for(int i=0;i<3;i++){float x=-7.5f+4.5f*i;box(r,"flask"+i+"_0",16,26,x,14,4,3,3,3,0);box(r,"flask"+i+"_1",16,23,x+.5f,17,4.5f,2,1,2,0);box(r,"flask"+i+"_2",24,24,x+1,17.5f,5,1,1,1,0);box(r,"flask"+i+"_3",28,27,x+.5f,14.5f,4.5f,2,3,2,0);box(r,"bowl"+i+"_0",36,24,x,14,4,3,1,3,0);box(r,"bowl"+i+"_1",36,20,x-.5f,15,4,1,1,3,0);box(r,"bowl"+i+"_2",36,20,x+2.5f,15,4,1,1,3,0);box(r,"bowl"+i+"_3",44,20,x,15,6.5f,3,1,1,0);box(r,"bowl"+i+"_4",44,20,x,15,3.5f,3,1,1,0);box(r,"bowl"+i+"_5",48,22,x+.5f,14.75f,4.5f,2,1,2,0);}return model=LayerDefinition.create(mesh,64,32).bakeRoot();}
 public static void draw(CuttingTable.Tile tile,Direction face,PoseStack pose,MultiBufferSource buffers,int light,int overlay){pose.pushPose();pose.translate(.5,0,.5);float rotation=switch(face){case SOUTH->180;case WEST->90;case EAST->270;default->0;};pose.mulPose(Axis.YP.rotationDegrees(rotation));var model=model();for(int i=0;i<3;i++){for(int j=0;j<4;j++)model.getChild("flask"+i+"_"+j).visible=false;for(int j=0;j<6;j++)model.getChild("bowl"+i+"_"+j).visible=false;}model.render(pose,buffers.getBuffer(RenderType.entityCutoutNoCull(TEXTURE)),light,overlay);
 if(tile!=null){for(int i=0;i<3;i++){var s=tile.getItem(i+1);var a=thaumcraft.api.aspects.Aspect.getAspect(CuttingTable.Tile.aspect(s));if(a==null)continue;boolean flask=s.getItem() instanceof tc4revival.content.EssentiaPhialItem;String prefix=(flask?"flask":"bowl")+i+"_";int count=flask?4:6;for(int n=0;n<count;n++){int j=flask?new int[]{2,3,0,1}[n]:n;var part=model.getChild(prefix+j);part.visible=true;boolean fluid=j==(flask?3:5);int rgb=fluid?a.getColor():0xffffff;part.render(pose,buffers.getBuffer(RenderType.entityTranslucent(TEXTURE)),light,overlay,(rgb>>16&255)/255f,(rgb>>8&255)/255f,(rgb&255)/255f,1);part.visible=false;}}
 if(!tile.getItem(0).isEmpty()){pose.pushPose();pose.translate(-.2,.875,-.25);pose.scale(.375f,.75f,.375f);pose.mulPose(Axis.XP.rotationDegrees(90));pose.translate(.5,.5,0);Minecraft.getInstance().getItemRenderer().renderStatic(tile.getItem(0),ItemDisplayContext.FIXED,light,overlay,pose,buffers,tile.getLevel(),0);pose.popPose();}}
 pose.popPose();}
 @Override public void render(CuttingTable.Tile tile,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){draw(tile,tile.getBlockState().getValue(SpinningWheel.FACING),pose,buffers,light,overlay);}
}
